head.script:
scwin.gVar = {
    "cRef" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[anchor > P > ref]<br/>컴포넌트의 내부 텍스트로 바인딩할 DataCollection 정보를 설정합니다.",
    "validation" : [
        "접근 가능한 DataCollection 의 컬럼을 'data:[DataCollection ID].[Key]' 형식으로 설정할 수 있어야 합니다.",
        "접근할 수 없는 DataCollection 정보이면 localeRef 또는 xf:label 태그에 설정한 내부 텍스트가 표시됩니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
};



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        ref: scwin.gVar["cRef"],
    };

    let cList = $c.gcm.createCList(properties);       

    $c.gcm.createBasicAnchor(cList);
}
